/* Public price snapshots. Missing observations are null; no synthetic prices or chart history. */
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?Math.round(n).toLocaleString('en-US'):'—';
const UNITS=[[1e9,'B'],[1e6,'M'],[1e3,'K']];
/* Compact values use three significant digits so neighbouring figures share one precision. */
const fmt=n=>{if(!Number.isFinite(n))return '—';if(Math.abs(n)<1e3)return +n.toFixed(2);let i=UNITS.findIndex(([v])=>Math.abs(n)>=v),v=+(n/UNITS[i][0]).toPrecision(3);if(Math.abs(v)>=1e3&&i>0){i--;v=+(n/UNITS[i][0]).toPrecision(3)}return v+UNITS[i][1]};
const pct=n=>(Math.abs(n)>=1e3?Math.round(n).toLocaleString('en-US'):n.toFixed(1))+'%';
/* Source quote grades, most to least reliable. */
const GRADES=['S','A','B','C','D'],gradeRank=g=>GRADES.includes(g)?GRADES.indexOf(g):GRADES.length;
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Browser storage unavailable. Changes last for this visit.')}}
const DATA=window.DT_DATA.items,META=window.DT_DATA.meta,RECIPES=window.DT_DATA.recipes,byId=new Map(DATA.map(d=>[d.id,d]));
const SPAWNERS=window.DT_DATA.spawners.types;
let spawnerInputs=read('dt-spawner-inputs-v1',{}),selectedSpawner=read('dt-spawner-selected-v1','skeleton');
if(!SPAWNERS.some(t=>t.id===selectedSpawner))selectedSpawner='skeleton';
const investmentIds=['elytra','dragon_head','piglin_head','enchanted_golden_apple'];
let watch=new Set(read('dt-watch-v2',[])),plans=read('dt-plans-v2',[]),profile=read('dt-profile',''),history=read('dt-history-v2',{});
let state={route:'home',query:'',category:'All',page:1,size:40,sort:'name',dir:1,flipTab:'crafting',budget:0,minProfit:0,grade:'B'};
let compareMode=false,compareItems=new Set();
let currentItem=null,context='market',returnFocus=null,observers=[],toastTimer,scrollBusy=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const snapshotTime=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(META.sourceTime));
const icon=d=>d.icon?`<img class="item-icon ${d.cube?'cube-icon':''} ${d.animated?'animated-icon':''} ${d.rendered?'native-render':''} ${d.flat?'flat-render':''}" src="assets/${esc(d.icon)}" alt="" width="32" height="32" loading="lazy" draggable="false">`:`<span class="item-placeholder" aria-hidden="true">${esc(d.name[0])}</span>`;
const price=d=>Number.isFinite(d.price)?`<span title="${num(d.price)} in-game dollars; rounded public quote">${d.rounded?'≈ ':''}${fmt(d.price)}</span>`:'<span class="price-unavailable">No quote</span>';
const movement=d=>Number.isFinite(d.change)?`<span class="${d.change<0?'negative':'positive'}">${d.change>0?'+':''}${d.change.toFixed(1)}%</span>`:'<span class="price-unavailable">—</span>';
const monthly=d=>Number.isFinite(history[d.id]?.average)?`<span title="Volume-weighted mean of imported October transactions">${fmt(history[d.id].average)}*</span>`:'<span class="price-unavailable">Unavailable</span>';
const star=d=>`<button class="watch-button ${watch.has(d.id)?'saved':''}" data-watch="${d.id}" aria-pressed="${watch.has(d.id)}" aria-label="${watch.has(d.id)?'Remove':'Add'} ${esc(d.name)} ${watch.has(d.id)?'from':'to'} watchlist">${watch.has(d.id)?'★':'☆'}</button>`;
const itemName=d=>`<span class="item-name">${icon(d)}<span>${esc(d.name)}<small>${esc(d.category)}${d.variantNote?' · Check variant':''}</small></span></span>`;
function toast(s){clearTimeout(toastTimer);$('.toast').textContent=s;$('.toast').classList.add('show');toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),3200)}
function updateStars(){ $('#watch-count').textContent=watch.size;$$('[data-watch]').forEach(b=>{let d=byId.get(b.dataset.watch);if(!d)return;const yes=watch.has(d.id);b.classList.toggle('saved',yes);b.textContent=yes?'★':'☆';b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',`${yes?'Remove':'Add'} ${d.name} ${yes?'from':'to'} watchlist`)})}
function toggleWatch(id){let d=byId.get(id);if(!d)return;watch.has(id)?watch.delete(id):watch.add(id);save('dt-watch-v2',[...watch]);updateStars();toast(watch.has(id)?`${d.name} saved`:`${d.name} removed`);if(state.route==='watchlist')updateResults()}
function craft(d){const recipes=RECIPES[d.id];if(!recipes||!Number.isFinite(d.price))return null;let best=null;for(const r of recipes){let total=0,lines=[],valid=true,grade=gradeRank(d.sourceGrade);for(const [id,count] of Object.entries(r.ingredients)){let x=byId.get(id);if(!x||!Number.isFinite(x.price)){valid=false;break}total+=x.price*count;grade=Math.max(grade,gradeRank(x.sourceGrade));lines.push({id,name:x.name,count,price:x.price})}if(valid){let cost=total/r.yield;if(!best||cost<best.cost)best={cost,yield:r.yield,lines,profit:d.price-cost,roi:(d.price-cost)/cost*100,grade:GRADES[grade]??null}}}return best}
const craftData=DATA.map(d=>({...d,recipe:craft(d)})).filter(d=>d.recipe&&d.recipe.cost>0);
function stats(){return `<div class="wrap stats-strip reveal"><div class="stat"><div class="stat-label">Minecraft items · Java 26.1</div><div class="stat-value">${num(META.catalogCount)}<small>Full versioned registry</small></div></div><div class="stat"><div class="stat-label">Published market quotes</div><div class="stat-value">${num(META.priceCount)}<small>Rounded source prices</small></div></div><div class="stat"><div class="stat-label">Recipes with priced ingredients</div><div class="stat-value">${num(craftData.length)}<small>Costs calculated per output</small></div></div><div class="stat"><div class="stat-label">Public price snapshot</div><div class="stat-value" style="font-size:19px">Oct 21, 2026<small>10:49 AM PDT · Not a live feed</small></div></div></div>`}
function sourceBanner(){return `<div class="source-status"><span><span class="coverage-dot"></span>Public price snapshot · Monthly averages require dated sales history.</span><button data-info="data">Sources & coverage ↗</button></div>`}
function miniInvest(){return `<div class="invest-mini">${investmentIds.map(id=>byId.get(id)).filter(Boolean).map(d=>`<div class="invest-mini-row"><button data-item="${d.id}" aria-label="View ${esc(d.name)}">${icon(d)}</button><button data-item="${d.id}" class="item-detail"><strong>${esc(d.name)}</strong><small>${d.category}</small></button><div class="investment-value">${price(d)}<small>${movement(d)} / 7d</small></div>${star(d)}</div>`).join('')}</div>`}
function itemMedia(d,i=0){return `<div class="item-stage ${d.id==='enchanted_golden_apple'?'enchanted-stage':''}"><span class="item-ground" aria-hidden="true"></span><div class="item-arrival"><div class="item-bob" style="--float-delay:-${i*.8}s"><div class="item-model">${icon(d)}</div></div></div><button class="inspect-item" data-inspect="${d.id}" aria-label="Inspect ${esc(d.name)} artwork"><span>⤢</span> Inspect</button></div>`}
function cards(data,featured=false){return `<div class="investment-grid" ${featured?'data-featured-grid':''}>${data.map((d,i)=>`<article class="investment-card motion-card reveal ${state.route==='investments'&&compareItems.has(d.id)?'compare-selected':''}" style="--delay:${i%4*60}ms" data-item="${d.id}" ${featured&&i<4?`data-investment-arrival="${i}"`:''} tabindex="0" aria-label="View ${esc(d.name)}"><span class="card-spotlight" aria-hidden="true"></span><span class="card-index">${esc(d.category.toUpperCase())}</span>${star(d)}${state.route==='investments'?`<button class="compare-pick" data-compare-id="${d.id}" aria-pressed="${compareItems.has(d.id)}" aria-label="${compareItems.has(d.id)?'Remove':'Select'} ${esc(d.name)} ${compareItems.has(d.id)?'from':'for'} comparison"><span aria-hidden="true">${compareItems.has(d.id)?'✓':'+'}</span><span>Compare</span></button>`:''}${itemMedia(d,i)}<h3>${esc(d.name)}</h3><div class="card-price">${price(d)} ${movement(d)}</div><div class="monthly-line"><span>October average</span>${monthly(d)}</div><div class="card-bottom"><span>PUBLIC QUOTE · 7D CHANGE</span><span class="card-arrow">↗</span></div></article>`).join('')}</div>`}
function spawnerStage(large=false,type=SPAWNERS[0]){const skeleton=type.id==='skeleton',mob=byId.get(type.icon);const art=skeleton?`<img class="spawner-art" src="assets/spawner.png" alt="Skeleton spawner" width="1402" height="1122" draggable="false" ${large?'':'fetchpriority="high"'}>`:`<div class="native-spawner-cage"><span class="spawner-glow" aria-hidden="true"></span>${mob?.icon?`<img class="spawner-mob ${mob.flat?'flat-render':''}" src="assets/${esc(mob.icon)}" alt="" width="256" height="256" draggable="false">`:''}<img class="spawner-art" src="assets/renders/spawner.png" alt="${esc(type.name)} spawner" width="256" height="256" draggable="false"></div>`;return `<div class="${large?'spawner-visual':'hero-stage'} spawner-interactive ${skeleton?'':'native-spawner-stage'}" data-spawner-stage tabindex="0" role="group" aria-label="Interactive ${esc(type.name)} spawner view. Drag or use arrow keys to tilt. Press Enter for embers."><div class="spawner-stage-inner"><div class="spawner-object">${art}</div></div><div class="ember-field" aria-hidden="true"></div><span class="stage-hint">↔ Drag to tilt</span>${large?`<div class="stage-type-badge">${icon(byId.get(type.icon))}<span>${esc(type.name)}</span></div>`:`<div class="price-tag"><small>SKELETON SPAWNER</small><strong>Price unverified</strong><a href="#/spawners">Open calculator ↗</a></div>`}<div class="spawner-controls"><button data-spawner-reset aria-label="Reset spawner view">↺ Reset</button><button data-spawner-pause aria-pressed="false">Ⅱ Pause</button><button data-spawner-embers aria-pressed="true">✦ Embers</button></div></div>`}
function recipeTable(data,full=false){return `<div class="table-scroll"><table class="market-table"><thead><tr><th>Item</th><th>Craft cost / item</th><th>Market quote</th><th>Recipe spread</th><th>ROI</th>${full?'<th>Save</th>':''}</tr></thead><tbody>${data.map(d=>`<tr data-item="${d.id}" data-context="crafting" tabindex="0" aria-label="View ${esc(d.name)} recipe"><td>${itemName(d)}</td><td>≈ ${fmt(d.recipe.cost)}</td><td>${price(d)}</td><td class="${d.recipe.profit>=0?'positive':'negative'}">${d.recipe.profit>0?'+':''}${fmt(d.recipe.profit)}</td><td class="${d.recipe.roi>=0?'positive':'negative'}">${pct(d.recipe.roi)}</td>${full?`<td>${star(d)}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function home(){let preferred=['beacon','diamond_chestplate','diamond_leggings','diamond_boots','firework_rocket'];let crafts=preferred.map(id=>craftData.find(d=>d.id===id)).filter(Boolean);return `<div class="page-enter"><section class="wrap hero"><div class="hero-copy"><div class="eyebrow">DONUT SMP · AUCTION & CRAFTING</div><h1>Market overview</h1><p class="hero-desc">Item prices, crafting costs, investments, and spawner calculations.</p><div class="hero-buttons"><a class="btn btn-primary" href="#/market">All ${num(DATA.length)} entries <span>↗</span></a><a class="text-link" href="#/flips">Compare crafting <span>→</span></a></div><div class="home-search-wrap"><form class="hero-search" id="home-search-form" role="search"><span aria-hidden="true">⌕</span><label class="visually-hidden" for="home-search">Search the item catalog</label><input id="home-search" autocomplete="off" placeholder="Search every item by name or Minecraft ID…"><kbd>/</kbd></form><div id="home-results"></div></div></div>${spawnerStage()}</section>${stats()}<section class="wrap market-section">${sourceBanner()}<div class="market-layout"><div class="reveal"><div class="panel-title"><h3>Crafting spreads</h3><a class="text-link" href="#/flips?tab=crafting">All recipes <span>↗</span></a></div>${recipeTable(crafts)}<p class="table-note">Computed from rounded market quotes. A spread is not a confirmed buyer or a realized profit.</p></div><div class="reveal" style="--delay:80ms"><div class="panel-title"><h3>Popular investments</h3><a class="text-link" href="#/investments">View all <span>↗</span></a></div>${miniInvest()}<p class="table-note">Current imported source quote · Change reported by the source over 7 days.</p></div></div></section><section class="wrap dashboard-tools"><a href="#/spawners" class="dashboard-tool reveal"><span>▦</span><div><h3>Spawner calculator</h3><p>Use your measured output and purchase price.</p></div><span>↗</span></a><a href="#/flips?tab=order" class="dashboard-tool reveal" style="--delay:50ms"><span>⇄</span><div><h3>Order flip planner</h3><p>Compare your buy order with a selling target.</p></div><span>↗</span></a><a href="#/watchlist" class="dashboard-tool reveal" style="--delay:100ms"><span>☆</span><div><h3>Watchlist & trade plans</h3><p>Saved in this browser.</p></div><span>↗</span></a></section></div>`}
function head(title,description,extra=''){return `<section class="wrap page-head page-enter"><div class="page-head-row"><div><h1>${title}</h1><p>${description}</p></div>${extra}</div></section>`}
function filterBar(crafting=false){return `<div class="filter-bar"><div class="search-box"><span>⌕</span><label class="visually-hidden" for="market-search">Search catalog</label><input id="market-search" placeholder="Search item name or Minecraft ID…" value="${esc(state.query)}" autocomplete="off"><button class="clear-search" data-action="clear-search" aria-label="Clear search" ${state.query?'':'hidden'}>×</button><kbd class="search-shortcut">/</kbd></div>${crafting?`<div class="filter-field"><label for="budget">Max craft / item</label><input id="budget" type="number" min="0" placeholder="Any" value="${state.budget||''}"></div><div class="filter-field" title="Source quote grade, S (most reliable) to D. A recipe takes the weakest grade of its output and ingredients."><label for="grade">Quote grade</label><select id="grade">${[['A','S–A only'],['B','S–B'],['C','S–C'],['D','All grades']].map(([g,label])=>`<option value="${g}" ${state.grade===g?'selected':''}>${label}</option>`).join('')}</select></div>`:''}<div class="filter-field"><label for="sort">Sort</label><select id="sort"><option value="name">Name A–Z</option><option value="price">Highest price</option><option value="change">7d gainers</option>${crafting?'<option value="profit">Recipe spread</option><option value="roi">Crafting ROI</option>':''}</select></div></div>`}
function marketPage(){return `${head('Item catalog',`${num(META.catalogCount)} Minecraft Java 26.1 items plus identified server items and variants. ${num(META.priceCount)} published quotes; unavailable prices stay blank.`)}<section class="wrap page-main page-enter">${sourceBanner()}${filterBar()}<div class="chips" aria-label="Item category">${['All','Priced','Blocks','Equipment','Redstone','Materials','Collectibles','Consumables','DonutSMP','Server variants'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><div id="results"></div><div id="pagination"></div></section>`}
function planner(kind){const auction=kind==='auction';return `<div class="manual-planner" data-planner="${kind}"><h3>${auction?'Auction flip planner':'Order flip planner'}</h3><p>${auction?'Enter a listing price you saw on the auction house and your resale target. Add a selling fee if your listings pay one. No auction feed is connected.':'Enter the price you will offer with a buy order and your selling target. Orders can take time to fill. No order-book feed is connected.'}</p><form id="manual-plan"><div class="planner-fields ${auction?'has-fee':''}"><div><label for="plan-item">Item</label><input id="plan-item" list="item-options" placeholder="Search an item…" required><datalist id="item-options">${DATA.map(d=>`<option value="${esc(d.name)} — ${d.id}"></option>`).join('')}</datalist></div><div><label for="manual-buy">${auction?'Listing price / item':'Order price / item'}</label><input id="manual-buy" type="number" min="0.01" step="0.01" required></div><div><label for="manual-sell">${auction?'Resell / item':'Sell / item'}</label><input id="manual-sell" type="number" min="0.01" step="0.01" required></div>${auction?'<div><label for="manual-fee">Selling fee %</label><input id="manual-fee" type="number" min="0" max="100" step="0.1" placeholder="Optional"></div>':''}<div><label for="manual-qty">Quantity</label><input id="manual-qty" type="number" min="1" max="1000000" value="64" required></div><button class="btn btn-primary" type="submit">Save plan <span>↗</span></button></div><div class="manual-summary"><span>Capital <strong id="manual-capital">—</strong></span><span>Spread <strong id="manual-profit">—</strong></span></div></form></div>`}
function flipsPage(){return `${head('Flips & crafting','Recipe costs use sourced ingredient quotes. Order and auction plans use prices you enter.')}<section class="wrap page-main page-enter"><div class="tabs page-tabs" role="tablist" aria-label="Flip type">${[['crafting','Crafting flips'],['order','Order flips'],['auction','Auction flips']].map(([id,name])=>`<button class="tab ${state.flipTab===id?'active':''}" role="tab" aria-selected="${state.flipTab===id}" data-flip-tab="${id}">${name}</button>`).join('')}</div><div id="flip-view">${state.flipTab==='crafting'?`${sourceBanner()}${filterBar(true)}<div id="results"></div><div id="pagination"></div>`:planner(state.flipTab)+`<div class="section-head"><h3>Saved trade plans</h3><a class="text-link" href="#/watchlist">Your watchlist <span>↗</span></a></div><div id="plans-list">${planList()}</div>`}</div></section>`}
function getSpawner(){return SPAWNERS.find(t=>t.id===selectedSpawner)||SPAWNERS[0]}
function spawnerForm(type){const saved=spawnerInputs[type.id]||{};return {count:saved.count??12,hours:saved.hours??6,purchase:saved.purchase??'',drops:Object.fromEntries(type.drops.map(id=>[id,{rate:saved.drops?.[id]?.rate??'',price:saved.drops?.[id]?.price??byId.get(id)?.price??''}]))}}
function inputAmount(value){if(value===null||value===undefined||String(value).trim()==='')return null;const n=Number(value);return Number.isFinite(n)&&n>=0?n:null}
function spawnerEstimate(count,hours,purchase,drops){const n=inputAmount(count),h=inputAmount(hours),p=inputAmount(purchase);if(n===null||n<1||!Number.isInteger(n)||h===null||h<=0||h>24||!drops.length)return {income:null,hourly:null,payback:null,lines:[],complete:false};let hourly=0,complete=true;const lines=drops.map(drop=>{const rate=inputAmount(drop.rate),price=inputAmount(drop.price);if(rate===null||rate>0&&price===null){complete=false;return {...drop,income:null}}const income=n*h*rate*(price??0);hourly+=n*rate*(price??0);return {...drop,income}});const income=complete?hourly*h:null;return {income,hourly:complete?hourly:null,payback:complete&&income>0&&p!==null&&p>0?n*p/income:null,lines,complete}}
function spawnerShowcase(){const type=getSpawner();return `<div class="spawner-active-title"><div><span class="eyebrow">SELECTED SPAWNER</span><h2>${esc(type.name)}</h2></div><span class="section-tag">${SPAWNERS.length} TYPES</span></div>${spawnerStage(true,type)}<div class="spawner-type-grid" role="group" aria-label="Spawner type">${SPAWNERS.map(t=>`<button class="spawner-type ${t.id===type.id?'active':''}" data-spawner="${t.id}" aria-pressed="${t.id===type.id}">${icon(byId.get(t.icon))}<span>${esc(t.name)}</span><span class="type-check" aria-hidden="true">${t.id===type.id?'✓':''}</span></button>`).join('')}</div>`}
function calculator(){const type=getSpawner(),form=spawnerForm(type);return `<div class="calculator advanced-calc multi-spawner-calc" data-calculator><div class="calc-top"><strong>${esc(type.name)} income</strong><small>YOUR INPUTS</small></div><label class="range-label" for="spawner-count">Spawner count <output data-out="count">${esc(form.count)}</output></label><input class="range" id="spawner-count" data-calc="count" type="range" min="1" max="4096" value="${esc(form.count)}"><div class="calc-count-entry"><label for="spawner-count-exact">Exact count</label><input id="spawner-count-exact" data-calc="exact-count" type="number" min="1" max="4096" step="1" value="${esc(form.count)}"></div><label class="range-label" for="online-hours">Online hours / day <output data-out="hours">${esc(form.hours)} hours</output></label><input class="range" id="online-hours" data-calc="hours" type="range" min="1" max="24" value="${esc(form.hours)}"><div class="calc-field purchase-field"><label for="calc-price">Your price / spawner</label><input id="calc-price" data-calc="price" type="number" min="0.01" step="0.01" value="${esc(form.purchase)}" placeholder="Enter price"></div><div class="drop-inputs"><div class="drop-inputs-heading"><strong>Drop production</strong><span>Use 0 to exclude a drop</span></div>${type.drops.map(id=>{const item=byId.get(id),values=form.drops[id];return `<div class="drop-input-row" data-drop="${id}"><div class="drop-name">${icon(item)}<strong>${esc(item.name)}</strong><output data-out="drop-${id}">Income: — / day</output></div><div class="drop-fields"><div><label for="calc-rate-${id}">Items / spawner / hour</label><input id="calc-rate-${id}" data-calc="rate" data-drop-rate="${id}" type="number" min="0" step="0.01" value="${esc(values.rate)}" placeholder="Measured rate" aria-label="${esc(item.name)} per spawner per hour"></div><div><label for="calc-drop-${id}">Selling price / item</label><input id="calc-drop-${id}" data-calc="drop" data-drop-price="${id}" type="number" min="0" step="0.01" value="${esc(values.price)}" placeholder="Your sell price" aria-label="${esc(item.name)} selling price"></div></div></div>`}).join('')}</div><p class="spawner-type-note">${esc(type.notes)}</p><div class="calc-result"><div><small>Estimated income / day</small><strong data-out="income">—</strong><span class="hourly-income" data-out="hourly">— / online hour</span></div><div class="payback"><small>Time to payback</small><strong data-out="payback">—</strong></div></div><p class="calc-note" data-out="status">Enter a measured rate for each drop. Use 0 for drops you will not sell.</p><div class="calc-footer"><span>Inputs saved per spawner type</span><button class="text-link" data-action="reset-spawner-inputs">Reset inputs ↺</button></div></div>`}
function spawnerPage(){return `${head('Spawner calculator','Choose from all nine documented Donut SMP spawner types. Calculate returns from your measured drops and purchase price.')}<section class="wrap page-main page-enter"><div class="spawner-page-grid"><div id="spawner-showcase">${spawnerShowcase()}</div><div id="spawner-calculator">${calculator()}</div></div><p id="spawner-type-status" class="visually-hidden" role="status"></p><details class="assumptions"><summary>Calculation, drops & sources</summary><p>Daily income = spawner count × online hours × the sum of (measured drop rate per spawner/hour × selling price per item). Payback = total purchase cost ÷ daily income. Enter each rate for the current farm setup and stack size; changing the number of stacked spawners can change output per spawner. No production curve is copied between mob types. Missing rates or selling prices leave the total unavailable. Use a rate of 0 to exclude a drop.</p><p>Drop prices are prefilled from the imported public snapshot (${snapshotTime}) and can be edited. Spawner purchase prices are not verified. Storage limits, downtime, unsold inventory, and other costs are not modeled.</p><p>Types and outputs: <a href="https://donut.today/wiki/spawners" target="_blank" rel="noopener noreferrer">Donut SMP community guide ↗</a>, <a href="https://donutpedia.wiki/wiki/Spawner" target="_blank" rel="noopener noreferrer">Donutpedia ↗</a>, and <a href="https://www.donutsmpstats.net/" target="_blank" rel="noopener noreferrer">DonutSMP Market spawner listings ↗</a>. Server behavior and available types can change; use your observed output.</p></details></section>`}
function switchSpawner(id,reset=false){if(!SPAWNERS.some(t=>t.id===id))return;if(reset)delete spawnerInputs[id];selectedSpawner=id;save('dt-spawner-selected-v1',id);save('dt-spawner-inputs-v1',spawnerInputs);$('#spawner-showcase').innerHTML=spawnerShowcase();$('#spawner-calculator').innerHTML=calculator();calcUpdate($('[data-calculator]'));window.DonutMotion?.mount($('#content'));window.DonutMotion?.selection($('#spawner-calculator'));$('#spawner-type-status').textContent=getSpawner().name+' spawner selected';$(`[data-spawner="${id}"]`)?.focus({preventScroll:true})}

function investmentPage(){return `${head('Popular investments','Source-reported market prices and seven-day changes. Monthly averages appear only when dated sales history has been imported.')}<section class="wrap page-main page-enter investment-page ${compareMode?'is-comparing':''}" data-investments>${sourceBanner()}<div class="investment-toolbar"><span class="featured-caption"><i></i> Featured items</span><div><button class="subtle-button" data-action="replay-investments"><span aria-hidden="true">↻</span> Replay entrance</button><button class="subtle-button" data-action="compare-mode" aria-pressed="${compareMode}"><span aria-hidden="true">⊞</span> Compare items <kbd>C</kbd></button></div></div><p class="compare-guidance" ${compareMode?'':'hidden'}>Choose 2–3 items to compare their quotes and seven-day changes.</p>${cards(investmentIds.map(id=>byId.get(id)).filter(Boolean),true)}<div class="section-head" style="margin-top:35px"><h3>Materials</h3><a class="text-link" href="#/market">Full catalog <span>↗</span></a></div>${cards(['netherite_ingot','diamond','gold_ingot','bone_block'].map(id=>byId.get(id)).filter(Boolean))}<div id="compare-dock-root"></div></section>`}
function setCompareMode(value){compareMode=value;const page=$('[data-investments]');if(!page)return;page.classList.toggle('is-comparing',value);$('[data-action="compare-mode"]').setAttribute('aria-pressed',String(value));$('.compare-guidance').hidden=!value;updateCompareDock()}
function toggleCompare(id){if(compareItems.has(id))compareItems.delete(id);else if(compareItems.size<3)compareItems.add(id);else{toast('Choose up to 3 items. Remove one to make room.');return}$$('.investment-card').forEach(card=>{const yes=compareItems.has(card.dataset.item);card.classList.toggle('compare-selected',yes);const button=$('[data-compare-id]',card);if(button){button.setAttribute('aria-pressed',String(yes));button.setAttribute('aria-label',`${yes?'Remove':'Select'} ${byId.get(card.dataset.item).name} ${yes?'from':'for'} comparison`);$('span',button).textContent=yes?'✓':'+'}});updateCompareDock();window.DonutMotion?.selection($(`.investment-card[data-item="${id}"]`))}
function updateCompareDock(){const root=$('#compare-dock-root');if(!root)return;const items=[...compareItems].map(id=>byId.get(id)).filter(Boolean);root.innerHTML=compareMode&&items.length?`<aside class="compare-dock" aria-label="Selected investments"><div class="compare-preview">${items.map(d=>`<button data-compare-id="${d.id}" aria-label="Remove ${esc(d.name)} from comparison">${icon(d)}<span>×</span></button>`).join('')}</div><span class="compare-count" role="status">${items.length} / 3 selected</span><button class="text-link" data-action="compare-clear">Clear</button><button class="btn btn-primary" data-action="compare-open" ${items.length<2?'disabled':''}>Compare <span>↗</span></button></aside>`:'';window.DonutMotion?.mount(root)}
function openComparison(){const items=[...compareItems].map(id=>byId.get(id)).filter(Boolean);if(items.length<2)return;showModal(`<div class="drawer-top"><small>INVESTMENT COMPARISON</small>${closeButton()}</div><h2 id="dialog-title">Compare your shortlist</h2><p class="comparison-note">Rounded source quotes. These are not guaranteed selling prices.</p><div class="comparison-grid" style="--compare-columns:${items.length}">${items.map(d=>`<div class="comparison-column"><button class="comparison-art" data-inspect="${d.id}" aria-label="Inspect ${esc(d.name)} artwork">${icon(d)}</button><h3>${esc(d.name)}</h3><dl><div><dt>Market quote</dt><dd>${price(d)}</dd></div><div><dt>7-day change</dt><dd>${movement(d)}</dd></div><div><dt>October average</dt><dd>${monthly(d)}</dd></div><div><dt>Stack size</dt><dd>${d.stack??'Unverified'}</dd></div></dl><button class="text-link" data-item="${d.id}">Trade details ↗</button></div>`).join('')}</div>`,'profile-modal comparison-modal')}

function planList(){return plans.length?plans.map((p,i)=>{const d=byId.get(p.id);return d?`<div class="journal-row"><div>${itemName(d)}<small class="muted">${num(p.qty)} items · ${esc(p.method)} · Unrealized</small></div><div><small class="muted">Planned spread</small><br><strong class="${p.profit>=0?'positive':'negative'}">${p.profit>0?'+':''}${fmt(p.profit)}</strong></div><button class="text-link" data-remove-plan="${i}">Remove ×</button></div>`:''}).join(''):`<div class="page-empty"><strong>No trade plans saved</strong>Open a recipe or enter prices in the order flip planner.</div>`}
function watchlistPage(){return `${head(profile?`${esc(profile)}’s watchlist`:'Watchlist & plans','Items and trade plans are saved in this browser.',`<a class="btn btn-ghost" href="#/market">Browse items <span>↗</span></a>`)}<section class="wrap page-main page-enter"><div id="results"></div><div class="journal-section"><div class="section-head"><h3>Trade plans</h3><span class="section-tag">${plans.length} SAVED</span></div><div id="plans-list">${planList()}</div></div></section>`}
function marketTable(data){return `<div class="table-scroll"><table class="market-table"><thead><tr><th>Item</th><th><button class="sort-btn" data-sort="price">Public price ↕</button></th><th><button class="sort-btn" data-sort="change">7d change ↕</button></th><th>October average</th><th>Stack</th><th>Save</th></tr></thead><tbody>${data.map(d=>`<tr data-item="${d.id}" tabindex="0" aria-label="View ${esc(d.name)}"><td>${itemName(d)}</td><td>${price(d)}</td><td>${movement(d)}</td><td>${monthly(d)}</td><td class="muted">${d.stack??'—'}</td><td>${star(d)}</td></tr>`).join('')}</tbody></table></div>`}
function filtered(){let data=state.route==='flips'?craftData:DATA;const terms=state.query.toLowerCase().split(/\s+/).filter(Boolean);data=data.filter(d=>terms.every(q=>(d.name+' '+d.id).toLowerCase().includes(q))&&(state.category==='All'||state.category==='Priced'&&Number.isFinite(d.price)||d.category===state.category));if(state.route==='watchlist')data=data.filter(d=>watch.has(d.id));if(state.route==='flips'&&state.budget)data=data.filter(d=>d.recipe.cost<=state.budget);if(state.route==='flips')data=data.filter(d=>gradeRank(d.recipe.grade)<=gradeRank(state.grade));let val=d=>state.sort==='name'?d.name:state.sort==='profit'?d.recipe?.profit:state.sort==='roi'?d.recipe?.roi:d[state.sort];return data.slice().sort((a,b)=>{let x=val(a),y=val(b);if(x==null&&y==null)return a.name.localeCompare(b.name);if(x==null)return 1;if(y==null)return-1;return (typeof x==='string'?x.localeCompare(y):x-y)*state.dir})}
function updateResults(){const root=$('#results');if(!root)return;const before=window.DonutMotion?.captureRows(root);const clear=$('[data-action="clear-search"]');if(clear)clear.hidden=!state.query;let data=filtered();if(state.route==='watchlist'){root.innerHTML=data.length?cards(data):`<div class="empty-state"><span class="icon-star">☆</span><h3>No items saved</h3><p>Use the star beside any item to add it here.</p><a class="btn btn-primary" href="#/market">Browse catalog <span>↗</span></a></div>`;window.DonutMotion?.rows(root,before);observe();return}const total=data.length,pages=Math.max(1,Math.ceil(total/state.size));state.page=Math.min(state.page,pages);const offset=(state.page-1)*state.size,slice=data.slice(offset,offset+state.size);root.innerHTML=slice.length?`<div class="full-table">${state.route==='flips'?recipeTable(slice,true):marketTable(slice)}</div>`:`<div class="empty-state"><h3>No matching items</h3><p>Try another search or category.</p><button class="btn btn-ghost" data-action="reset">Reset filters</button></div>`;$('#pagination').innerHTML=`<div class="pagination"><span>${total?offset+1:0}–${Math.min(offset+state.size,total)} of ${num(total)} entries</span><div><label class="visually-hidden" for="page-size">Rows per page</label><select id="page-size"><option value="20" ${state.size===20?'selected':''}>20 rows</option><option value="40" ${state.size===40?'selected':''}>40 rows</option><option value="80" ${state.size===80?'selected':''}>80 rows</option></select><button data-page="prev" ${state.page===1?'disabled':''}>← Previous</button><span>${state.page} / ${pages}</span><button data-page="next" ${state.page===pages?'disabled':''}>Next →</button></div></div>`;window.DonutMotion?.rows(root,before);window.DonutMotion?.mount($('#content'))}
function route(){closeModal(false);observers.forEach(o=>o.disconnect());observers=[];const raw=location.hash.replace(/^#\/?/,'')||'home',[r,q]=raw.split('?');const url=new URLSearchParams(q);let next=['home','market','flips','spawners','investments','watchlist'].includes(r)?r:'home';if(next!=='investments')compareMode=false;state={...state,route:next,query:url.get('q')||'',category:'All',page:1,sort:next==='flips'?'profit':'name',dir:next==='flips'?-1:1,flipTab:['crafting','order','auction'].includes(url.get('tab'))?url.get('tab'):'crafting',budget:0};const pages={home,market:marketPage,flips:flipsPage,spawners:spawnerPage,investments:investmentPage,watchlist:watchlistPage};$('#content').innerHTML=pages[next]();document.title=`${({home:'Market overview',market:'Item catalog',flips:'Flips & crafting',spawners:'Spawner calculator',investments:'Investments',watchlist:'Watchlist'})[next]} — Donut Tracker`;$$('[data-route]').forEach(a=>{const yes=a.dataset.route===next;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('.desktop-nav').classList.remove('open');$('.mobile-toggle').setAttribute('aria-expanded','false');if($('#sort'))$('#sort').value=state.sort;updateResults();updateStars();observe();scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});bindTilt();if(next==='spawners')calcUpdate($('[data-calculator]'));if(next==='investments')updateCompareDock();onScroll()}
function observe(){const observer=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('visible');observer.unobserve(x.target)}}),{threshold:.03});$$('.reveal:not(.visible)').forEach(el=>observer.observe(el));observers.push(observer);window.DonutMotion?.mount($('#content'))}
function onScroll(){if(scrollBusy)return;scrollBusy=true;requestAnimationFrame(()=>{scrollBusy=false;const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.width=`${max>0?scrollY/max*100:0}%`;$('#header').classList.toggle('scrolled',scrollY>20)})}
function bindTilt(){window.DonutMotion?.mount($('#content'))}
function shell(contents,kind='drawer'){return `<div class="modal-backdrop" data-action="close"></div><section class="${kind}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${contents}</section>`}
function showModal(contents,kind='drawer'){returnFocus=document.activeElement;$('#modal-root').innerHTML=shell(contents,kind);document.body.classList.add('no-scroll');$('.drawer-close')?.focus();window.DonutMotion?.mount($('#modal-root'))}
function closeModal(focus=true){$('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');currentItem=null;if(focus&&returnFocus?.isConnected)returnFocus.focus()}
function closeButton(){return '<button class="drawer-close" data-action="close" aria-label="Close dialog">×</button>'}
function openItem(id,ctx='market'){const d=byId.get(id);if(!d)return;context=ctx;const art=window.DonutMotion?.captureArt($$('[data-item]').find(e=>e.dataset.item===id&&e.querySelector('.item-icon'))?.querySelector('.item-icon'));const recipe=ctx==='crafting'?craft(d):null,alt=window.DT_DATA.alternates[d.id],hist=history[d.id];showModal(`<div class="drawer-top"><small>ITEM DETAILS</small>${closeButton()}</div><div class="detail-heading">${icon(d)}<div><h2 id="dialog-title">${esc(d.name)}</h2><p>${esc(d.id)}</p></div></div><div><span class="detail-price">${price(d)}</span><span class="detail-change">${movement(d)} <span class="muted">/ 7d</span></span></div><div class="detail-metrics"><div><small>October average</small><strong>${monthly(d)}</strong></div><div><small>Stack size</small><strong>${d.stack??'Unverified'}</strong></div></div><div class="detail-source">${d.source?`Source: <a href="${d.source}" target="_blank" rel="noopener noreferrer">DonutSMP Terminal ↗</a><br>Published snapshot: ${snapshotTime}<br>Prices imported from rounded public labels.`:'No verified quote is available for this catalog entry.'}${d.variantNote?`<br>${esc(d.variantNote)}.`:''}${hist?`<br>October import: ${num(hist.transactions)} transactions, ${num(hist.quantity)} items; sample coverage ${esc(hist.first)} to ${esc(hist.last)}. Weighted mean = total unit price × quantity ÷ total quantity.`:''}</div>${alt?`<div class="detail-source">Alternate displayed value: <strong>${fmt(alt.price)}</strong><br><a href="${alt.source}" target="_blank" rel="noopener noreferrer">Donut.Auction ↗</a> · Observed Oct 21. Source history may be stale; this is not a monthly average.</div>`:''}<div class="chart-unavailable">No verified price series imported.<br>Monthly history is not generated from the current quote.</div>${recipe?`<h3 class="recipe-heading">Recipe: ${recipe.yield} output ${recipe.yield===1?'item':'items'}</h3>${recipe.lines.map(l=>`<div class="recipe-line"><button class="recipe-ingredient" data-item="${l.id}">${icon(byId.get(l.id))}<span>${num(l.count)} × ${esc(l.name)}</span><span class="ingredient-arrow">↗</span></button><strong>≈ ${fmt(l.price*l.count)}</strong></div>`).join('')}<div class="recipe-line"><span>Ingredient cost / output item</span><strong>≈ ${fmt(recipe.cost)}</strong></div>`:''}<div class="trade-plan"><h3>Trade plan</h3><p>Enter your observed prices. No trade is executed.</p><div class="detail-form-row"><div><label for="detail-buy">Buy / item</label><input id="detail-buy" type="number" min="0.01" step="0.01" value="${recipe?recipe.cost.toFixed(2):''}" placeholder="Your buy price"></div><div><label for="detail-sell">Sell / item</label><input id="detail-sell" type="number" min="0.01" step="0.01" value="${d.price??''}" placeholder="Your selling target"></div></div><label class="range-label" for="plan-quantity">Quantity <output id="quantity-output">64 items</output></label><input class="range" id="plan-quantity" type="range" min="1" max="512" value="64"><div class="plan-output"><span>Capital required</span><b id="plan-cost">${recipe?fmt(recipe.cost*64):'—'}</b></div><div class="plan-output"><span>Estimated spread</span><strong id="plan-profit">${recipe?fmt(recipe.profit*64):'—'}</strong></div><button class="btn btn-primary" data-action="save-plan" ${!recipe?'disabled':''}>Save trade plan <span>↗</span></button><p class="calc-note">Selling time, available quantities, and additional costs are not included.</p></div><div class="drawer-actions"><button class="btn btn-ghost" data-action="detail-watch">${watch.has(d.id)?'★ Watching':'☆ Add to watchlist'}</button><button class="btn btn-ghost" data-action="copy-item">Copy Minecraft ID ⧉</button></div>`);currentItem=d;window.DonutMotion?.flyArt(art,$('.detail-heading .item-icon'))}
function openInspector(id){const d=byId.get(id);if(!d)return;showModal(`<div class="drawer-top"><small>ITEM VIEWER · NATIVE INVENTORY RENDER</small>${closeButton()}</div><h2 id="dialog-title">${esc(d.name)}</h2><div class="interactive-item-view" data-inspect-stage tabindex="0" role="group" aria-label="Drag or use arrow keys to tilt ${esc(d.name)} artwork"><div class="viewer-grid" aria-hidden="true"></div><div class="viewer-bob"><div class="viewer-spin"><div class="viewer-object">${icon(d)}</div></div></div><span class="viewer-hint">Drag to tilt · Scroll to zoom · Double-click to reset</span></div><div class="viewer-controls"><div class="viewer-button-group"><button class="btn btn-ghost" data-viewer-reset>↺ Reset</button><button class="btn btn-ghost" data-viewer-rotate aria-pressed="false">↻ Rotate</button></div><label for="viewer-zoom">Zoom <input id="viewer-zoom" data-viewer-zoom type="range" min="70" max="140" value="100"></label></div><div class="viewer-bottom"><span>${esc(d.id)}</span><button class="text-link" data-item="${d.id}">Price & trade details <span>↗</span></button></div>`,'profile-modal item-viewer')}
function updateDetail(){if(!currentItem)return;const b=+$('#detail-buy').value,s=+$('#detail-sell').value,q=+$('#plan-quantity').value;$('#quantity-output').textContent=q+' items';$('#plan-cost').textContent=b>0?fmt(b*q):'—';$('#plan-profit').textContent=b>0&&s>0?fmt((s-b)*q):'—';$('#plan-profit').classList.toggle('negative',s<b);$('[data-action="save-plan"]').disabled=!(b>0&&s>0)}
function calcUpdate(root){if(!root)return;const type=getSpawner(),count=$('#spawner-count-exact',root).value,hours=$('#online-hours',root).value,purchase=$('#calc-price',root).value,drops=type.drops.map(id=>({id,rate:$(`[data-drop-rate="${id}"]`,root).value,price:$(`[data-drop-price="${id}"]`,root).value})),result=spawnerEstimate(count,hours,purchase,drops);$('[data-out="count"]',root).textContent=count||'—';$('[data-out="hours"]',root).textContent=hours+' hours';$('[data-out="income"]',root).textContent=fmt(result.income);$('[data-out="hourly"]',root).textContent=fmt(result.hourly)+' / online hour';$('[data-out="payback"]',root).textContent=result.payback===null?'—':fmt(result.payback)+' days';for(const id of type.drops)$(`[data-out="drop-${id}"]`,root).textContent='Income: '+fmt(result.lines.find(line=>line.id===id)?.income??null)+' / day';$('[data-out="status"]',root).textContent=!result.complete?'Enter a measured rate for every drop and a selling price for each included drop. Use 0 to exclude a drop.':result.income===0?'No income at these inputs. Payback requires positive income.':'Uses your entered rates and prices. Re-measure production when changing stack size. Purchase price is required for payback.';spawnerInputs[type.id]={count,hours,purchase,drops:Object.fromEntries(drops.map(d=>[d.id,{rate:d.rate,price:d.price}]))};save('dt-spawner-inputs-v1',spawnerInputs)}
function profileModal(){showModal(`<div class="drawer-top"><small>LOCAL PROFILE</small>${closeButton()}</div><h2 id="dialog-title">Profile name</h2><p>Your profile, watchlist, and trade plans stay in this browser. No Minecraft connection is created.</p><form id="profile-form"><label for="profile-name">Display name</label><input id="profile-name" value="${esc(profile)}" maxlength="24" required autocomplete="nickname"><button class="btn btn-primary" type="submit">Save profile <span>↗</span></button></form>`,'profile-modal');$('#profile-name').focus()}
function sourcesModal(){showModal(`<div class="drawer-top"><small>DATA COVERAGE</small>${closeButton()}</div><h2 id="dialog-title">Sources & coverage</h2><p>The catalog contains all ${num(META.catalogCount)} entries in Minecraft Java 26.1, plus identified server items and source variants. Server availability is not guaranteed for every vanilla item.</p><div class="source-grid"><div><a href="https://github.com/PrismarineJS/minecraft-data" target="_blank" rel="noopener noreferrer">Minecraft catalog & recipes ↗</a><small>PrismarineJS minecraft-data · Java 26.1 registry · MIT license</small></div><div><a href="https://donutsmpterminal.com/all_items" target="_blank" rel="noopener noreferrer">DonutSMP Terminal market quotes ↗</a><small>${num(META.priceCount)} rounded public quotes. Snapshot ${snapshotTime}. Seven-day change is reported by the source; no synthetic history.</small></div><div><a href="https://donut.auction" target="_blank" rel="noopener noreferrer">Donut.Auction alternate displayed values ↗</a><small>25 separately attributed observations. The source warns that transaction history may be incomplete. Values are not October averages.</small></div><div><a href="https://api.donutsmp.net" target="_blank" rel="noopener noreferrer">Official Donut SMP API ↗</a><small>Requires an authorized API key. None is included in this site. Another website’s credentials are not used.</small></div></div><p style="margin-top:22px">A verified month-to-date average requires dated transactions. Import your own October sales CSV to calculate a volume-weighted average from that sample.</p><button class="btn btn-ghost" data-action="import" style="margin-top:20px">Import sales CSV <span>↑</span></button><p class="calc-note">CSV columns: item, unitPrice, quantity, timestamp. Item accepts a Minecraft ID or exact catalog name. Dates must include a timezone. Only Oct 1–21, 2026 sales are included. Imports stay in this browser. Item art: native Minecraft inventory renders by Owen1212055/mc-assets, fallback Minecraft textures, and AI-generated spawner artwork.</p>`,'profile-modal')}
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const split=l=>(l.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)||[]).filter(x=>x!=='').map(x=>x.replace(/,$/,'').replace(/^"|"$/g,'').replace(/""/g,'"'));const heads=split(lines.shift());return lines.map(l=>Object.fromEntries(split(l).map((v,i)=>[heads[i],v])))}
async function importSales(file){try{let rows=parseCSV(await file.text()),out={},invalid=0;for(const r of rows){let raw=String(r.item||'').replace(/^minecraft:/,''),d=byId.get(raw)||DATA.find(d=>d.name.toLowerCase()===raw.toLowerCase());let price=Number(r.unitPrice),qty=Number(r.quantity),ts=String(r.timestamp||''),time=Date.parse(ts);if(!d||!Number.isFinite(price)||price<=0||!Number.isSafeInteger(qty)||qty<=0||!/(Z|[+-]\d\d:\d\d)$/.test(ts)||!Number.isFinite(time)){invalid++;continue}const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(time));if(day<'2026-10-01'||day>'2026-10-21'){invalid++;continue}let a=out[d.id]??{total:0,quantity:0,transactions:0,first:day,last:day};a.total+=price*qty;a.quantity+=qty;a.transactions++;a.first=day<a.first?day:a.first;a.last=day>a.last?day:a.last;out[d.id]=a}let count=Object.keys(out).length;if(!count){toast('No valid October sales found. Check CSV columns and dated timestamps.');return}for(const a of Object.values(out))a.average=a.total/a.quantity;history={...history,...out};save('dt-history-v2',history);closeModal();updateResults();toast(`October sample averages imported for ${count} items. ${invalid} rows skipped.`)}catch{toast('Could not read the CSV. Use item, unitPrice, quantity, timestamp columns.')}}
function manualFee(){const f=+($('#manual-fee')?.value||0);return Number.isFinite(f)&&f>=0&&f<=100?f:0}
function updateManual(){const b=+$('#manual-buy').value,s=+$('#manual-sell').value,q=+$('#manual-qty').value,f=manualFee();$('#manual-capital').textContent=b>0&&q>0?fmt(b*q):'—';$('#manual-profit').textContent=b>0&&s>0&&q>0?fmt((s*(1-f/100)-b)*q):'—'}
function addPlan(d,buy,sell,qty,method,fee=0){plans.unshift({id:d.id,buy,sell,qty,fee,profit:(sell*(1-fee/100)-buy)*qty,method,created:new Date().toISOString()});save('dt-plans-v2',plans);toast('Trade plan saved');if($('#plans-list'))$('#plans-list').innerHTML=planList()}
document.addEventListener('click',ev=>{const el=ev.target.closest('button,a,[data-item]');if(!el)return;
 if(el.classList.contains('skip')){ev.preventDefault();$('#content').focus();return}
 if(el.dataset.watch){ev.preventDefault();ev.stopPropagation();const adding=!watch.has(el.dataset.watch);const art=window.DonutMotion?.captureArt(el.closest('[data-item],.invest-mini-row')?.querySelector('.item-icon'));toggleWatch(el.dataset.watch);window.DonutMotion?.burst(el);if(adding)window.DonutMotion?.saveFlight(art);return}
 if(el.dataset.compareId){ev.preventDefault();toggleCompare(el.dataset.compareId);return}
 if(el.dataset.inspect){ev.preventDefault();openInspector(el.dataset.inspect);return}
 if(el.dataset.item){ev.preventDefault();if(compareMode&&el.matches('.investment-card')){toggleCompare(el.dataset.item);return}openItem(el.dataset.item,el.dataset.context||'market');return}
 if(el.dataset.info){sourcesModal();return}
 if(el.dataset.spawner){ev.preventDefault();switchSpawner(el.dataset.spawner);return}
 if(el.dataset.category){state.category=el.dataset.category;state.page=1;$$('[data-category]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});updateResults();return}
 if(el.dataset.sort){state.dir=state.sort===el.dataset.sort?-state.dir:-1;state.sort=el.dataset.sort;updateResults();return}
 if(el.dataset.flipTab){location.hash='/flips?tab='+el.dataset.flipTab;return}
 if(el.dataset.page){state.page+=el.dataset.page==='next'?1:-1;updateResults();$('#results').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'});return}
 if(el.dataset.removePlan!==undefined){plans.splice(+el.dataset.removePlan,1);save('dt-plans-v2',plans);$('#plans-list').innerHTML=planList();toast('Trade plan removed');return}
 switch(el.dataset.action){
  case'reset-spawner-inputs':switchSpawner(selectedSpawner,true);break;
  case'replay-investments':window.DonutMotion?.replayInvestments($('[data-investments]'));break;
  case'compare-mode':setCompareMode(!compareMode);break;
  case'compare-clear':compareItems.clear();setCompareMode(compareMode);$$('.compare-selected').forEach(c=>c.classList.remove('compare-selected'));$$('[data-compare-id]').forEach(b=>{b.setAttribute('aria-pressed','false');$('span',b).textContent='+';b.setAttribute('aria-label',`Select ${byId.get(b.dataset.compareId).name} for comparison`)});break;
  case'compare-open':openComparison();break;
  case'clear-search':state.query='';state.page=1;$('#market-search').value='';updateResults();$('#market-search').focus();break;
  case'close':closeModal();break;
  case'profile':profileModal();break;
  case'menu':{let yes=!$('.desktop-nav').classList.contains('open');$('.desktop-nav').classList.toggle('open',yes);el.setAttribute('aria-expanded',yes);break}
  case'top':ev.preventDefault();scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'});break;
  case'reset':state.query='';state.category='All';state.budget=0;state.page=1;if($('#market-search'))$('#market-search').value='';if($('#budget'))$('#budget').value='';$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category==='All');b.setAttribute('aria-pressed',b.dataset.category==='All')});updateResults();break;
  case'detail-watch':if(currentItem){toggleWatch(currentItem.id);el.textContent=watch.has(currentItem.id)?'★ Watching':'☆ Add to watchlist'}break;
  case'copy-item':if(currentItem&&navigator.clipboard)navigator.clipboard.writeText(currentItem.id).then(()=>toast('Minecraft ID copied')).catch(()=>toast('Select the ID above to copy it.'));break;
  case'save-plan':if(currentItem){let b=+$('#detail-buy').value,s=+$('#detail-sell').value,q=+$('#plan-quantity').value;if(b>0&&s>0&&q>0){addPlan(currentItem,b,s,q,context==='crafting'?'Recipe quote':'Manual prices');el.textContent='Plan saved ✓';el.disabled=true}}break;
  case'import':{let input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.addEventListener('change',()=>{if(input.files[0])importSales(input.files[0])});input.click();break}
 }
});
document.addEventListener('input',ev=>{const t=ev.target;
 if(t.dataset.calc){if(t.dataset.calc==='count')$('#spawner-count-exact').value=t.value;if(t.dataset.calc==='exact-count'){$('#spawner-count').value=t.value;window.DonutMotion?.rangeFill($('#spawner-count'))}calcUpdate(t.closest('[data-calculator]'));return}
 if(t.id==='market-search'){state.query=t.value;state.page=1;updateResults()}
 if(t.id==='budget'){state.budget=Math.max(0,+t.value||0);state.page=1;updateResults()}
 if(['detail-buy','detail-sell','plan-quantity'].includes(t.id))updateDetail();
 if(['manual-buy','manual-sell','manual-qty','manual-fee'].includes(t.id))updateManual();
 if(t.id==='plan-item'){let id=t.value.split(' — ').at(-1),d=byId.get(id);if(d&&d.price!=null){$('#manual-sell').value=d.price;updateManual()}}
 if(t.id==='home-search'){const q=t.value.trim().toLowerCase(),res=q?DATA.filter(d=>(d.name+' '+d.id).toLowerCase().includes(q)).slice(0,6):[];$('#home-results').innerHTML=q?`<div class="home-search-results">${res.length?res.map(d=>`<button data-item="${d.id}">${icon(d)}<span>${esc(d.name)}</span><span>${Number.isFinite(d.price)?fmt(d.price):'No quote'} ↗</span></button>`).join(''):'<p style="font-size:11px;padding:12px">No matching catalog entries.</p>'}</div>`:''}
});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='sort'){state.sort=t.value;state.dir=t.value==='name'?1:-1;state.page=1;updateResults()}if(t.id==='page-size'){state.size=+t.value;state.page=1;updateResults()}if(t.id==='grade'){state.grade=t.value;state.page=1;updateResults()}});
document.addEventListener('submit',ev=>{
 if(ev.target.id==='home-search-form'){ev.preventDefault();location.hash='/market?q='+encodeURIComponent($('#home-search').value)}
 if(ev.target.id==='profile-form'){ev.preventDefault();profile=$('#profile-name').value.trim().slice(0,24);if(profile){save('dt-profile',profile);closeModal();location.hash='/watchlist';toast('Profile saved')}}
 if(ev.target.id==='manual-plan'){ev.preventDefault();let raw=$('#plan-item').value,id=raw.split(' — ').at(-1),d=byId.get(id)||DATA.find(d=>d.name.toLowerCase()===raw.toLowerCase()),b=+$('#manual-buy').value,s=+$('#manual-sell').value,q=+$('#manual-qty').value;if(!d){toast('Choose a catalog item from the item suggestions.');return}if(b>0&&s>0&&Number.isInteger(q)&&q>0)addPlan(d,b,s,q,state.flipTab==='auction'?'Auction flip':'Order flip',manualFee())}
});
document.addEventListener('keydown',ev=>{const dialog=$('[role="dialog"]');if(ev.key==='Escape'){closeModal();$('.desktop-nav').classList.remove('open');$('.mobile-toggle').setAttribute('aria-expanded','false');if($('#home-results'))$('#home-results').innerHTML='';if(compareMode&&!dialog)setCompareMode(false)}
 if(ev.key==='Tab'&&dialog){const all=$$('button,a[href],input,select,[tabindex="0"]',dialog).filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}
 if(ev.key==='Enter'&&ev.target.matches('[data-item]')&&!ev.target.matches('button')){ev.preventDefault();if(compareMode&&ev.target.matches('.investment-card'))toggleCompare(ev.target.dataset.item);else openItem(ev.target.dataset.item,ev.target.dataset.context||'market')}
 if(ev.key.toLowerCase()==='c'&&!dialog&&state.route==='investments'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){ev.preventDefault();setCompareMode(!compareMode)}
 if(ev.key==='Escape'&&ev.target.id==='market-search'&&state.query){state.query='';ev.target.value='';updateResults()}
 if(ev.key==='ArrowDown'&&ev.target.id==='home-search'){$('#home-results button')?.focus();ev.preventDefault()}
 if(['ArrowUp','ArrowDown'].includes(ev.key)&&ev.target.closest('.home-search-results')){ev.preventDefault();const options=$$('.home-search-results button'),i=options.indexOf(ev.target);if(ev.key==='ArrowUp'&&i===0)$('#home-search').focus();else options[(i+(ev.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}
 if(ev.key==='/'&&!dialog&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){ev.preventDefault();($('#home-search')||$('#market-search'))?.focus()}
});
document.addEventListener('click',ev=>{if(!ev.target.closest('.home-search-wrap')&&$('#home-results'))$('#home-results').innerHTML=''});
window.addEventListener('hashchange',()=>{if(document.startViewTransition&&!reduced.matches){const v=document.startViewTransition(route);v.finished.catch(()=>{})}else route()});window.addEventListener('scroll',onScroll,{passive:true});route();
